package com.bank.pm;

import java.time.LocalDate;

public class ActionItem {
    private final String description;
    private final String owner;          // a team/role, must be present
    private final LocalDate dueDate;     // must be present

    public ActionItem(String description, String owner, LocalDate dueDate) {
        if (owner == null || owner.isBlank())
            throw new IllegalArgumentException("Action item needs an owner");
        if (dueDate == null)
            throw new IllegalArgumentException("Action item needs a due date");
        this.description = description;
        this.owner = owner;
        this.dueDate = dueDate;
    }

    public String getDescription() { return description; }
    public String getOwner() { return owner; }
    public LocalDate getDueDate() { return dueDate; }

    @Override public String toString() {
        return "- " + description + " [owner=" + owner + ", due=" + dueDate + "]";
    }
}
