package com.bank.pm;

import java.util.List;

public class Postmortem {
    private final String incidentId;
    private final String summary;
    private final String timeline;
    private final String impact;
    private final String rootCause;
    private final String resolution;
    private final List<ActionItem> actionItems;

    public Postmortem(String incidentId, String summary, String timeline, String impact,
                      String rootCause, String resolution, List<ActionItem> actionItems) {
        this.incidentId = incidentId;
        this.summary = summary;
        this.timeline = timeline;
        this.impact = impact;
        this.rootCause = rootCause;
        this.resolution = resolution;
        this.actionItems = actionItems;
    }

    public String render() {
        StringBuilder sb = new StringBuilder();
        sb.append("Blameless Postmortem ").append(incidentId).append("\n");
        sb.append("  Summary:    ").append(summary).append("\n");
        sb.append("  Timeline:   ").append(timeline).append("\n");
        sb.append("  Impact:     ").append(impact).append("\n");
        sb.append("  Root cause: ").append(rootCause).append("\n");
        sb.append("  Resolution: ").append(resolution).append("\n");
        sb.append("  Action items (systems, owned, dated):\n");
        for (ActionItem a : actionItems) sb.append("    ").append(a).append("\n");
        return sb.toString();
    }
}
