package com.bank.pm;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class PostmortemBuilder {
    private static final Logger log = Logger.getLogger(PostmortemBuilder.class.getName());
    // Phrases that indicate PERSON blame — rejected to keep it blameless.
    private static final String[] BLAME_WORDS = {"fault of", "to blame", "should be fired",
        "careless", "stupid mistake", "'s fault"};

    private String incidentId, summary, timeline, impact, rootCause, resolution;
    private final List<ActionItem> actionItems = new ArrayList<>();

    public PostmortemBuilder incidentId(String v) { this.incidentId = v; return this; }
    public PostmortemBuilder summary(String v) { this.summary = checkBlameless(v); return this; }
    public PostmortemBuilder timeline(String v) { this.timeline = v; return this; }
    public PostmortemBuilder impact(String v) { this.impact = v; return this; }
    public PostmortemBuilder rootCause(String v) { this.rootCause = checkBlameless(v); return this; }
    public PostmortemBuilder resolution(String v) { this.resolution = v; return this; }
    public PostmortemBuilder actionItem(ActionItem a) { this.actionItems.add(a); return this; }

    // Reject person-blaming language: root cause must be about SYSTEMS.
    private String checkBlameless(String text) {
        String lower = text.toLowerCase();
        for (String bad : BLAME_WORDS) {
            if (lower.contains(bad)) {
                throw new IllegalArgumentException(
                    "Blameful language rejected ('" + bad + "'). Reframe to a SYSTEM cause: "
                    + "ask why the system allowed it, not who did it.");
            }
        }
        return text;
    }

    public Postmortem build() {
        if (actionItems.isEmpty())
            throw new IllegalStateException("A postmortem with no action items changes nothing");
        log.info(() -> "Postmortem " + incidentId + " passed blameless + action-item checks.");
        return new Postmortem(incidentId, summary, timeline, impact, rootCause,
            resolution, actionItems);
    }
}
