package com.bank.pm;

import java.time.LocalDate;
import java.util.logging.*;

public class BlamelessPostmortemDemo {
    private static final Logger log = Logger.getLogger(BlamelessPostmortemDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("=== Attempt 1: blameful root cause is REJECTED ===");
        try {
            new PostmortemBuilder().incidentId("INC-2048")
                .rootCause("It was the fault of the engineer who deployed v6.0");
        } catch (IllegalArgumentException e) {
            log.severe(() -> "Rejected: " + e.getMessage());
        }

        log.info("=== Attempt 2: blameless, system-focused postmortem ===");
        Postmortem pm = new PostmortemBuilder()
            .incidentId("INC-2048")
            .summary("transfer-api 5xx spiked to 40% for 18 minutes after a deploy")
            .timeline("03:10 alert; 03:12 SEV1; 03:16 rollback; 03:18 recovered")
            .impact("~25,000 customers could not transfer for 18 min; no data loss")
            .rootCause("A schema change removed an index; CI had no index-presence check, so a "
                + "slow query reached production unguarded (SYSTEM gap, not a person).")
            .resolution("Rolled back to v5.9; latency returned to baseline in 2 minutes")
            .actionItem(new ActionItem("Add index-presence check to CI pipeline",
                "platform-team", LocalDate.of(2026, 11, 7)))
            .actionItem(new ActionItem("Add canary with auto-rollback on 5xx regression",
                "release-eng", LocalDate.of(2026, 11, 14)))
            .actionItem(new ActionItem("Add DB latency burn-rate SLO alert",
                "sre-team", LocalDate.of(2026, 11, 10)))
            .build();
        log.info(() -> "\n" + pm.render());
    }
}
